class TrieNode:
    def __init__(self):
        self.children = {}
        self.index = -1

class WordFilter:
    def __init__(self, words):
        self.root = TrieNode()
        for idx, word in enumerate(words):
            n = len(word)
            for k in range(n + 1):
                combo = word[k:] + '#' + word                    # suffix + separator + full word
                node = self.root
                node.index = idx
                for c in combo:
                    node = node.children.setdefault(c, TrieNode())
                    node.index = idx                                    # overwrite with the LATEST (largest) index

    def f(self, prefix, suffix):
        combo = suffix + '#' + prefix                             # search key: suffix + separator + prefix
        node = self.root
        for c in combo:
            if c not in node.children:
                return -1
            node = node.children[c]
        return node.index

