import java.util.*;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    int index = -1;
}

class WordFilter {
    TrieNode root = new TrieNode();

    WordFilter(String[] words) {
        for (int idx = 0; idx < words.length; idx++) {
            String word = words[idx];
            int n = word.length();
            for (int k = 0; k <= n; k++) {
                String combo = word.substring(k) + '#' + word;         // suffix + separator + full word
                TrieNode node = root;
                node.index = idx;
                for (char c : combo.toCharArray()) {
                    node = node.children.computeIfAbsent(c, x -> new TrieNode());
                    node.index = idx;                                     // overwrite with the LATEST (largest) index
                }
            }
        }
    }

    int f(String prefix, String suffix) {
        String combo = suffix + '#' + prefix;                       // search key: suffix + separator + prefix
        TrieNode node = root;
        for (char c : combo.toCharArray()) {
            if (!node.children.containsKey(c)) return -1;
            node = node.children.get(c);
        }
        return node.index;
    }
}

