#include <bits/stdc++.h>
using namespace std;

struct TrieNode { unordered_map<char, TrieNode*> children; int index = -1; };

class WordFilter {
public:
    TrieNode* root = new TrieNode();

    WordFilter(vector<string>& words) {
        for (int idx = 0; idx < (int)words.size(); idx++) {
            string word = words[idx];
            int n = word.size();
            for (int k = 0; k <= n; k++) {
                string combo = word.substr(k) + '#' + word;              // suffix + separator + full word
                TrieNode* node = root;
                node->index = idx;
                for (char c : combo) {
                    if (!node->children.count(c)) node->children[c] = new TrieNode();
                    node = node->children[c];
                    node->index = idx;                                       // overwrite with the LATEST (largest) index
                }
            }
        }
    }

    int f(string prefix, string suffix) {
        string combo = suffix + '#' + prefix;                          // search key: suffix + separator + prefix
        TrieNode* node = root;
        for (char c : combo) {
            if (!node->children.count(c)) return -1;
            node = node->children[c];
        }
        return node->index;
    }
};
